WITH x AS (SELECT entity_key, total_views FROM entity_performance WHERE total_views IS NOT NULL), y AS (SELECT *, SUM(total_views) OVER () AS grand_total, SUM(total_views) OVER (ORDER BY total_views DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM x) SELECT entity_key,total_views,CASE WHEN grand_total>0 THEN running_total/grand_total END AS cumulative_share FROM y ORDER BY total_views DESC;
